declare
   l_return clob;
   l_count  int := 0;
   l_user_tags varchar2(4000) := null;
begin
   for c1 in (select upper(tags) tags from sp_team_members where id = :APP_USER_ID and tags is not null) loop
       l_user_tags := c1.tags;
   end loop;
   for c1 in (
      select notification_description 
      from SP_APPLICATION_NOTIFICATIONS 
      where (from_date is null or sysdate >= from_date) and
            (to_date   is null or sysdate <= to_date) and 
            (required_user_tag is null or instr(l_user_tags,required_user_tag) > 0) and
            is_active_yn = 'Y') loop
      --
      --
      --
      l_count := l_count + 1;
      if l_count = 2 then 
          l_return := '<ul><li>'||l_return||'</li>';
      end if;
      if l_count >= 2 then
         l_return := l_return||'<li>';
      end if;
      l_return := l_return||apex_escape.html(c1.notification_description);
      if l_count >= 2 then
         l_return := l_return||'</li>';
      end if;
   end loop;
   --
   --
   --
   if l_count >= 2 then
      l_return := l_return||'</ul>';
   end if;
   --
   --
   --
   return l_return;
end;

declare
    l_return  varchar2(4000) := null;
begin

if :APPROVALS_PENDING_CNT > 0 and :APPROVALS_MORE_INFO_CNT > 0 then
    if :APPROVALS_PENDING_CNT = 1 then
        l_return := 'You have 1 pending '|| :NOMENCLATURE_PROJECT ||' approval request.';
    else
        l_return := 'You have '|| :APPROVALS_PENDING_CNT ||' pending '|| :NOMENCLATURE_PROJECT ||' approval requests.';
    end if;
    if :APPROVALS_MORE_INFO_CNT = 1 then
        l_return := l_return || '<br/>You have 1 request for more information regarding your '|| :NOMENCLATURE_PROJECT ||' approval request.';
    else
        l_return := l_return || '<br/>You have '|| :APPROVALS_MORE_INFO_CNT ||' requests for more information regarding your '|| :NOMENCLATURE_PROJECT ||' approval requests.';
    end if;
elsif :APPROVALS_PENDING_CNT > 0 then
    if :APPROVALS_PENDING_CNT = 1 then
        l_return := 'You have 1 pending '|| :NOMENCLATURE_PROJECT ||' approval request.';
    else
        l_return := 'You have '|| :APPROVALS_PENDING_CNT ||' pending '|| :NOMENCLATURE_PROJECT ||' approval requests.';
    end if;
elsif :APPROVALS_MORE_INFO_CNT > 0 then
    if :APPROVALS_MORE_INFO_CNT = 1 then
        l_return := 'You have 1 request for more information regarding your '|| :NOMENCLATURE_PROJECT ||' approval request.';
    else
        l_return := 'You have '|| :APPROVALS_MORE_INFO_CNT ||' requests for more information regarding your '|| :NOMENCLATURE_PROJECT ||' approval requests.';
    end if;
end if;

return l_return;

end;

declare
    x clob;
begin
x := 'No description provided.';
for c1 in (select description from sp_projects d 
            where d.id = :P3_PROJECT_ID
              and description is not null) loop
    x := apex_markdown.to_html(c1.description);
end loop;
return x;
end;

declare
    l_changes_yn      varchar2(1);
    l_change_summary  clob;
begin

    sp_contributor_summary.project_changes (
        p_team_member_id => :P5_ID,
        p_frequency      => 'WEEKLY',
        p_links          => 'APP',
        p_apex_session   => :APP_SESSION,
        p_exclude_user_yn => nvl(:P5_PROJ_CHANGE_EXCLUDE_USER_YN,'N'),
        p_changes_yn     => l_changes_yn,
        p_change_summary => l_change_summary );

    if l_changes_yn = 'Y' then
        return l_change_summary;
    else
        return 'No changes found for projects you own or have favorited.';
    end if;

end;

declare
    l_count_0    number;
    l_count_100  number;
    l_owner      varchar2(4000);
    l_link       varchar2(4000);
    l_return     clob;
begin
    select count(*)
      into l_count_0
      from sp_projects p
     where pct_complete = 0
       and owner_id = :P5_ID
       and archived_yn = 'N';

    select count(*)
      into l_count_100
      from sp_projects p
     where pct_complete = 100
       and owner_id = :P5_ID
       and archived_yn = 'N';

    if l_count_0 > 0 or l_count_100 > 0 then
       select first_name||' '||last_name
         into l_owner
         from sp_team_members 
        where id = :P5_ID;
    end if;

    if l_count_0 > 0 or l_count_100 > 0 then
       l_link := '<a href="'||apex_page.get_url(
                                   p_application => :APP_ID,
                                   p_page        => 23,
                                   p_session     => :APP_SESSION,
                                   p_items       => 'P23_THE_OWNER',
                                   p_values      => l_owner,
                                   p_plain_url   => TRUE )||'">view all</a>';
    end if;

    if l_count_0 > 0 and l_count_100 > 0 then
       l_return := 'Report excludes '|| l_count_0 ||' and '||
                    l_count_100 || ' ' ||
                    :NOMENCLATURE_PROJECTS ||' owned by this user ('||l_link||').';
    elsif l_count_0 > 0 then
       l_return := 'Report excludes '||l_count_0 || ' '||
                    case when l_count_0 = 1 then :NOMENCLATURE_PROJECT else :NOMENCLATURE_PROJECTS end ||'  owned by this user ('||l_link||').';
    elsif l_count_100 > 0 then
       l_return := 'Report excludes '||l_count_100 || ' '||
                    case when l_count_100 = 1 then :NOMENCLATURE_PROJECT else :NOMENCLATURE_PROJECTS end ||'  owned by this user ('||l_link||').';
    end if;

    return '<br/>'||l_return;
 end;

declare
   s clob;
   l number;
   r clob;
   l_offset int := 1;
begin
   for c1 in (
       select TO_CLOB(DOCUMENT_BLOB) x
       from SP_PROJECT_DOCUMENTS
       where id = :P30_ID
   ) loop
          s := c1.x;
   end loop;
   l := dbms_lob.getlength(s);
   r := '<pre>'||chr(10);
   for i in 1..2000 loop
       if l_offset > dbms_lob.getlength(s) then 
          exit;
       else
          r := r||apex_escape.html(dbms_lob.substr(s,5000,l_offset));
          l_offset := l_offset + 5000;
       end if;
   end loop;
   r := r||chr(10)||'</pre>';
   return r;
end;

