declare

  insufficient_data exception;
  lv_stack_rank number;

begin

if :P4_DRAG_FOCUS_AREA_ID is null 
  or :P4_DROP_FOCUS_AREA_ID is null 
  or :P4_DRAG_ITEM_ID is null 
  or :P4_DRAG_COLUMN_ID is null 
  or :P4_DROP_COLUMN_ID is null 
  or :P4_INITIATIVE_ID is null
  or :P4_SR_ABOVE is null
  or :P4_SR_BELOW is null then
  raise insufficient_data;
end if;

if :P4_SR_ABOVE != 'None' and :P4_SR_BELOW != 'None' then

  select sum(kb_stack_rank) / 2 into lv_stack_rank from sp_projects
  where initiative_id = :P4_INITIATIVE_ID and id in (:P4_SR_ABOVE,:P4_SR_BELOW);

  update sp_projects set kb_stack_rank = lv_stack_rank
  where id = :P4_DRAG_ITEM_ID and initiative_id = :P4_INITIATIVE_ID;

elsif :P4_SR_ABOVE = 'None' and :P4_SR_BELOW != 'None' then

  select kb_stack_rank -1 into lv_stack_rank from sp_projects
  where initiative_id = :P4_INITIATIVE_ID and id = :P4_SR_BELOW;

  update sp_projects set kb_stack_rank = lv_stack_rank
  where id = :P4_DRAG_ITEM_ID and initiative_id = :P4_INITIATIVE_ID;

elsif :P4_SR_ABOVE != 'None' and :P4_SR_BELOW = 'None' then

  select kb_stack_rank +1 into lv_stack_rank from sp_projects
  where initiative_id = :P4_INITIATIVE_ID and id = :P4_SR_ABOVE;

  update sp_projects set kb_stack_rank = lv_stack_rank 
  where id = :P4_DRAG_ITEM_ID and initiative_id = :P4_INITIATIVE_ID;

end if;


if :P4_DRAG_FOCUS_AREA_ID != :P4_DROP_FOCUS_AREA_ID then
  update sp_projects
  set focus_area_id = decode(:P4_DROP_FOCUS_AREA_ID,'Unallocated',null,:P4_DROP_FOCUS_AREA_ID)
  where id = :P4_DRAG_ITEM_ID and initiative_id = :P4_INITIATIVE_ID;
end if;

if :P4_DRAG_COLUMN_ID != :P4_DROP_COLUMN_ID then
  update sp_projects
  set pct_complete = decode(:P4_DROP_COLUMN_ID,1,20,2,30,3,40,4,50,5,80)
  where id = :P4_DRAG_ITEM_ID and initiative_id = :P4_INITIATIVE_ID;
end if;

exception

  when insufficient_data then RAISE_APPLICATION_ERROR(-20001, 'Insufficient Data!');  

end;

